#ifndef DOC_RECURRENCE_VALUES_H
#define DOC_RECURRENCE_VALUES_H
/* Host argument admission and storage for versioned source authority.
 * The graph-specific frontier and dependency policy is generated by DOC. */
typedef struct {uint64_t epoch;size_t id;V value;} Fact;
static int epoch_number(const char *s,size_t n,uint64_t *out){if(!n)return 0;uint64_t v=0;for(size_t i=0;i<n;i++){unsigned c=(unsigned char)s[i];if(c<'0'||c>'9'||v>(UINT64_MAX-(c-'0'))/10)return 0;v=v*10+(c-'0');}*out=v;return 1;}
static int store_fact(Region *owner,V *out,int kind,const char *input){jmp_buf jump;failure_target=&jump;failure_message=NULL;if(setjmp(jump)){failure_target=NULL;return 0;}Region tmp;push(&tmp);*out=own(owner,input_value(kind,input));pop(&tmp);failure_target=NULL;return 1;}
static int store_value(Region *owner,V *out,V v){jmp_buf jump;failure_target=&jump;failure_message=NULL;if(setjmp(jump)){failure_target=NULL;return 0;}*out=own(owner,v);failure_target=NULL;return 1;}
 #include "checkpoint_io.h"
#include "recurrence_policy_generated.h"
static int recurrence_carry_admitted(int source,int target,int same,int unbound){return truth(F_rec_carry(vb(source),vb(target),vb(same),vb(unbound)));}
/* Shared initial and successor candidate construction. A caller can validate
 * typed projections or external device results before the same epoch commit. */
static int recurrence_prepare(Epoch *e,int initial){
    if(!e->in_flight)return 0;
    if(!truth(F_rec_prepare(vb(e->in_flight),vb(!e->batch_state),vb(initial),vb(e->committed>0)))){e->batch_state=1;return 0;}
    return 1;
}
static int recurrence_reject(Epoch *e){if(e->in_flight)e->batch_state=1;return 0;}
static int recurrence_initial_candidate(Epoch *e,Region *owner,V *defaults,const V *restored){
    if(!recurrence_prepare(e,1))return 0;
    if(!owner||!defaults)return recurrence_reject(e);
    int ok=1;size_t target;
    for(int pass=0;pass<2&&ok;pass++)for(size_t i=0;i<e->n&&ok;i++)if(truth(F_rec_initial(vi(pass),vi(e->states[i].role)))){
        ok=evaluate(e,i,NULL);if(ok)publish_private(e,i);
        if(ok)ok=store_value(owner,&defaults[i],*e->states[i].slot);
    }
    if(restored)for(size_t i=0;i<e->n&&ok;i++)if(source_role(e->states[i].role)){
        Cell *c=e->cell+i;ok=restored[i].kind==e->states[i].kind&&store_value(&c->candidate,&c->result,restored[i]);if(ok)publish_private(e,i);
    }
    return ok?batch(e,0,NULL,&target):recurrence_reject(e);
}
static int recurrence_successor_candidate(Epoch *e,const size_t *carry,const V *defaults,const Fact *facts,size_t nf,uint64_t ep){
    if(!recurrence_prepare(e,0))return 0;
    if(!carry||!defaults||(nf&&!facts)||!ep)return recurrence_reject(e);
    /* Check host-supplied authority before touching any private value. All
     * carries read only the admitted previous generation, even cycles. */
    for(size_t i=0;i<e->n;i++)if(carry[i]!=e->n){
        size_t j=carry[i];int present=j<e->n&&e->states[j].name&&e->saved_have[j]&&!e->saved_dirty[j];
        if(!truth(F_rec_carry(vb(source_role(e->states[i].role)),vb(present),vb(present&&e->states[i].kind==e->states[j].kind),vb(1))))return recurrence_reject(e);
    }
    for(size_t j=0;j<nf;j++)if(facts[j].epoch==ep){
        size_t i=facts[j].id;int valid=i<e->n&&e->states[i].name;
        int unique=1;for(size_t k=0;k<j;k++)if(facts[k].epoch==ep&&facts[k].id==i){unique=0;break;}
        if(!truth(F_rec_fact(vb(valid&&source_role(e->states[i].role)),vb(valid&&carry[i]==e->n),vb(ep>0),vb(1),vb(unique),vb(valid&&facts[j].value.kind==e->states[i].kind))))return recurrence_reject(e);
    }
    int ok=1;size_t target;
    for(size_t i=0;i<e->n&&ok;i++)if(source_role(e->states[i].role)){
        const Fact *fact=NULL;for(size_t j=0;j<nf;j++)if(facts[j].epoch==ep&&facts[j].id==i){fact=facts+j;break;}
        int pick=(int)num(F_rec_pick(vb(carry[i]!=e->n),vb(fact!=NULL)));
        if(pick<0)return recurrence_reject(e);
        V v=pick==2?fact->value:pick==1?e->cell[carry[i]].previous:defaults[i];
        Cell *c=e->cell+i;ok=v.kind==e->states[i].kind&&store_value(&c->candidate,&c->result,v);if(ok)publish_private(e,i);
    }
    return ok?batch(e,0,NULL,&target):recurrence_reject(e);
}
static int run_recurrence(Epoch *e,int argc,char **argv){uint64_t cap=0;size_t halt=e->n,at=0,nf=0;int ok=0;Region fact_owner={0},default_owner={0},restore_owner={0};const char *save=NULL,*load=NULL,*audio=NULL;V *restored=NULL;uint64_t saved_epoch=0,published=0;size_t *carry=zalloc(e->n,sizeof(*carry));Fact *facts=zalloc((size_t)argc,sizeof(*facts));V *defaults=zalloc(e->n,sizeof(*defaults));if(!carry||!facts||!defaults)goto done;for(size_t i=0;i<e->n;i++)carry[i]=e->n;
    if(!strncmp(argv[at],"--through=",10)){const char *s=argv[at++]+10;if(!epoch_number(s,strlen(s),&cap))goto done;}
    else {halt=find_state(e,argv[at]+8,strlen(argv[at]+8));at++;if(halt==e->n||e->states[halt].kind!=B||at>=(size_t)argc||strncmp(argv[at],"--max-epochs=",13))goto done;const char *s=argv[at++]+13;if(!epoch_number(s,strlen(s),&cap))goto done;}
    for(;at<(size_t)argc;at++){const char *arg=argv[at];if(!strncmp(arg,"--save=",7)){if(save||!arg[7])goto done;save=arg+7;}else if(!strncmp(arg,"--load=",7)){if(load||!arg[7])goto done;load=arg+7;}else if(!strncmp(arg,"--audio-dir=",12)){if(audio||!arg[12])goto done;audio=arg+12;}else if(!strncmp(arg,"--fact=",7)){const char *colon=strchr(arg+7,':'),*eq=colon?strchr(colon+1,'='):NULL;uint64_t ep;if(!colon||!eq||!epoch_number(arg+7,(size_t)(colon-arg-7),&ep)||!ep||ep>cap)goto done;size_t i=find_state(e,colon+1,(size_t)(eq-colon-1));if(i==e->n||!source_role(e->states[i].role))goto done;for(size_t j=0;j<nf;j++)if(facts[j].epoch==ep&&facts[j].id==i)goto done;if(!store_fact(&fact_owner,&facts[nf].value,e->states[i].kind,eq+1))goto done;facts[nf].epoch=ep;facts[nf++].id=i;}
        else {const char *eq=strchr(arg,'=');if(!eq)goto done;size_t i=find_state(e,arg,(size_t)(eq-arg)),j=find_state(e,eq+1,strlen(eq+1));if(!truth(F_rec_carry(vb(i<e->n&&source_role(e->states[i].role)),vb(j<e->n),vb(i<e->n&&j<e->n&&e->states[i].kind==e->states[j].kind),vb(i<e->n&&carry[i]==e->n))))goto done;carry[i]=j;}}
    for(size_t j=0;j<nf;j++){Fact *f=facts+j;if(!truth(F_rec_fact(vb(source_role(e->states[f->id].role)),vb(carry[f->id]==e->n),vb(f->epoch>0),vb(f->epoch<=cap),vb(1),vb(f->value.kind==e->states[f->id].kind))))goto done;}
    if((save||load||audio)&&(!doc_output_root||!checkpoint_enabled()))goto done;
    if(load){restored=zalloc(e->n,sizeof(*restored));if(!restored||!checkpoint_load(e,carry,load,&restore_owner,restored,&saved_epoch))goto done;}
    if(!epoch_begin(e))goto done;
    int initial_ok=recurrence_initial_candidate(e,&default_owner,defaults,restored);
    if(!epoch_finish(e,initial_ok))goto done;
    clear(&restore_owner);free(restored);restored=NULL;
    if(load)fprintf(stderr,"DOC11_CHECKPOINT_RESTORED: saved_epoch=%llu new_epoch=0\n",(unsigned long long)saved_epoch);
    for(uint64_t ep=0;;ep++){
        if(ep&&audio&&!checkpoint_audio(e,audio,ep))break;
        published=ep;observe(e,e->n,1,(size_t)ep);fprintf(stderr,"DOC11_RECURRENCE_EPOCH: %llu evaluations=%zu frontiers=%zu parallel=%zu\n",(unsigned long long)ep,e->evaluations,e->frontiers,e->parallel_frontiers);
        int stop=(int)num(F_rec_stop(vb(halt!=e->n),vb(halt!=e->n&&truth(*e->states[halt].slot)),vb(ep==cap)));
        if(stop){if(halt!=e->n&&stop>0)printf("DOC_RECURRENCE_HALT: %llu\n",(unsigned long long)ep);ok=stop>0;break;}
        if(!epoch_begin(e))break;
        int success=recurrence_successor_candidate(e,carry,defaults,facts,nf,ep+1);
        if(!epoch_finish(e,success))break;
    }
    if(ok&&save){ok=checkpoint_save(e,carry,published,save);if(ok)fprintf(stderr,"DOC11_CHECKPOINT_SAVED: epoch=%llu\n",(unsigned long long)published);}
done:clear(&restore_owner);free(restored);clear(&fact_owner);clear(&default_owner);free(carry);free(facts);free(defaults);if(!ok)fprintf(stderr,"DOC: recurrence rejected or halt cap exhausted; previous publication retained\n");return ok;
}
#undef F_rec_prepare
#undef F_rec_initial
#undef F_rec_carry
#undef F_rec_fact
#undef F_rec_pick
#undef F_rec_stop
#endif
